-- Audit trail of every scoring rule that fired for a GI endoscopy request.

CREATE TABLE endoscopy_test_request_grade_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    endoscopy_test_request_grade_id UUID NOT NULL
        REFERENCES endoscopy_test_request_grade(id) ON DELETE CASCADE,
    rule_id VARCHAR(40) NOT NULL,
    axis VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (axis IN ('appropriateness', 'urgency', 'completeness', 'risk', '')),
    category VARCHAR(50) NOT NULL DEFAULT '',
    description VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_endoscopy_test_request_grade_rule_grade_id
    ON endoscopy_test_request_grade_rule(endoscopy_test_request_grade_id);

CREATE TRIGGER trigger_endoscopy_test_request_grade_rule_updated_at
    BEFORE UPDATE ON endoscopy_test_request_grade_rule
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE endoscopy_test_request_grade_rule IS
    'Audit trail of every appropriateness / urgency / completeness / risk rule that fired for this request.';
COMMENT ON COLUMN endoscopy_test_request_grade_rule.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN endoscopy_test_request_grade_rule.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN endoscopy_test_request_grade_rule.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN endoscopy_test_request_grade_rule.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN endoscopy_test_request_grade_rule.endoscopy_test_request_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN endoscopy_test_request_grade_rule.rule_id IS
    'Stable rule identifier (e.g. R-URGENCY-2WW-DYSPHAGIA-01).';
COMMENT ON COLUMN endoscopy_test_request_grade_rule.axis IS
    'Scoring axis the rule belongs to: appropriateness, urgency, completeness, risk.';
COMMENT ON COLUMN endoscopy_test_request_grade_rule.category IS
    'Category or indication the rule relates to.';
COMMENT ON COLUMN endoscopy_test_request_grade_rule.description IS
    'Human-readable description of why the rule fired.';

-- ========================================================================
-- END 06_create_table_endoscopy_test_request_grade_rule.sql
